import os, sys, zlib
def parse(buf):
    out = []
    for i in range(len(buf)):
        if buf[i] == 0x1f:
            out.append(buf[i+1:i+9])
    return out
data = open('target.bin','rb').read()
for chunk in parse(data):
    print(zlib.crc32(chunk))
